ns:RegisterSpecGuide("WARLOCK", "Affliction", {
	role = "caster",
	stats = { "Hit Rating", "Spell Power", "Haste Rating", "Critical Strike Rating", "Spirit", "Intellect" },
	enchants = {
		{ slot = "Head", options = { { kind = "item", id = 50368, enchant = 3820, name = "Arcanum of Burning Mysteries" }, { kind = "item", id = 44075, enchant = 3797, name = "Arcanum of Dominance" } },
		  note = "Arcanum of Burning Mysteries from Kirin Tor revered reputation is the choice for warlocks. If you aren't revered yet you can make use of Arcanum of Dominance for 40 Stone Keeper's Shards." },
		{ slot = "Shoulder", options = { { kind = "spell", id = 61120, enchant = 3838, skill = "Inscription", craft = "Inscription" }, { kind = "item", id = 50338, enchant = 3810, name = "Greater Inscription of the Storm " } },
		  note = "If you have Inscription then {spell:61120} is a no-brainer, however as we know from the profession section in the overview, this isn't the most optimal profession for Warlocks.\n\nFor everyone else who doesn't have Inscription, Greater Inscription of the Storm from The Sons of Hodir will be the go-to. This requires exalted but only needs to be farmed once and it's a huge value enchant." },
		{ slot = "Back", options = { { kind = "spell", id = 55642, enchant = 3722, skill = "Tailoring", craft = "Tailoring" }, { kind = "spell", id = 63765, enchant = 3859, skill = "Engineering", craft = "Engineering" }, { kind = "item", id = 39003, enchant = 3831, name = "Scroll of Enchant Cloak - Greater Speed" } },
		  note = "It might seem like there is a lot of choices when it comes to cloak enchants however, it all depends on your profession of choice. If you are a tailor and want to get the most out of it you need to make use of {spell:55642}. This provides you with a 35% chance to proc a buff providing 295 spell power for the next 15 seconds (60-second ICD).\n\nIf you don't have Tailoring but have Engineering you will want to make use of {spell:63765}, not only does it give you a slowfall parachute for whenever you please, but also the flat 27 spell power is superior to your normal cloak enchant. If all else fails you want to make use of Scroll of Enchant Cloak - Greater Speed." },
		{ slot = "Chest", options = { { kind = "item", id = 38928, enchant = 1144, name = "Scroll of Enchant Chest - Major Spirit" }, { kind = "item", id = 44465, enchant = 3832, name = "Scroll of Enchant Chest - Powerful Stats" } },
		  note = "Scroll of Enchant Chest - Major Spirit provides us with the biggest DPS increase due to the fact of how well Warlocks scale with spirit ({spell:47893} & {spell:64248}). However, Scroll of Enchant Chest - Powerful Stats only provides 5 spirit less and gains us a tiny bit of damage from the intellect, plus a bit of survivability through the extra stamina, this is mostly a preference choice." },
		{ slot = "Wrist", options = { { kind = "spell", id = 57691, enchant = 3758, skill = "Leatherworking", craft = "Leatherworking" }, { kind = "item", id = 44470, enchant = 2332, name = "Scroll of Enchant Bracer - Superior Spellpower" } },
		  note = "If you have Leatherworking then {spell:57691} is a no-brainer, however as we know from the profession section in the overview, this isn't the most optimal profession for Warlocks.\n\nFor everyone else who doesn't have Leatherworking, Scroll of Enchant Bracer - Superior Spellpower is the best wrist enchant." },
		{ slot = "Hands", options = { { kind = "spell", id = 54999, enchant = 3604, skill = "Engineering", craft = "Engineering" }, { kind = "item", id = 38979, enchant = 3246, name = "Scroll of Enchant Gloves - Exceptional Spellpower" } },
		  note = "Engineering is one of the go-to recommended Warlock professions. One of the many benefits is {spell:54999}. This enchant provides us with a big on-use haste buff, ideal for mixing up with other precious cooldowns or key moments.\n\nIf you lack Engineering you will want to opt for Scroll of Enchant Gloves - Exceptional Spellpower." },
		{ slot = "Waist", options = { { kind = "item", id = 41611, name = "Eternal Belt Buckle" } },
		  note = "Eternal Belt Buckle can be crafted by any Blacksmithing and added to your belt in order to obtain an extra gem socket which then provides bonus stats.\n\n{spell:54793} can only be used by Engineering and stacks with Eternal Belt Buckle. This allows for the free use of Cobalt Frag Bomb, note that this does less damage compared to Saronite Bomb and puts both on cooldown, and has a half-second cast time." },
		{ slot = "Legs", options = { { kind = "spell", id = 56039, enchant = 3872, skill = "Tailoring", craft = "Tailoring" }, { kind = "item", id = 41602, enchant = 3719, name = "Brilliant Spellthread" }, { kind = "item", id = 41601, enchant = 3718, name = "Shining Spellthread" } },
		  note = "Brilliant Spellthread is definitely the choice with the most offensive stats of any of the leg enchants available. {spell:56039} can be used if you have Tailoring instead, it provides the same stats but is cheaper to make. Shining Spellthread is a slightly worse but much less expensive alternative. PvP players may prefer the Earthen Leg Armor due to the combination of stamina and resilience which typically is not highly valued by PvE players." },
		{ slot = "Feet", options = { { kind = "spell", id = 55016, enchant = 3606, skill = "Engineering", craft = "Engineering" }, { kind = "item", id = 39006, enchant = 3232, name = "Scroll of Enchant Boots - Tuskarr's Vitality" }, { kind = "spell", id = 60623, enchant = 3826, craft = "Enchanting" } },
		  note = "You want to be sure to have one movement speed increasing effect, {spell:55016} from Engineering fulfill this role the best. If you don't have Engineering you should go for Scroll of Enchant Boots - Tuskarr's Vitality. If you don't value movement speed increases on your boots you can always still opt for {spell:60623}." },
		{ slot = "Weapon", options = { { kind = "item", id = 44467, enchant = 3834, name = "Scroll of Enchant Weapon - Mighty Spellpower" }, { kind = "item", id = 45056, enchant = 3854, name = "Scroll of Enchant Staff - Greater Spellpower" } },
		  note = "Scroll of Enchant Weapon - Mighty Spellpower is an exceptional enchantment for warlocks and it is not something you want to miss. Scroll of Enchant Staff - Greater Spellpower should be used instead if you use a staff.\n\n{spell:59625} is also an option, though on average it results in less of a DPS increase compared to spell power until late end game content, in which case the value of haste increases making this equal or slightly better." },
		{ slot = "Ring", options = { { kind = "spell", id = 44636, enchant = 3840, skill = "Enchanting", craft = "Enchanting" } },
		  note = "If you're an enchanter you can enchant your rings as well as your other armor and weapons. For warlocks {spell:44636} is the superior choice." },
	},
	gems = {
		{ slot = "Meta", options = { { kind = "item", id = 41285, name = "Chaotic Skyflare Diamond" }, { kind = "item", id = 34220, name = "Chaotic Skyfire Diamond" } },
		  note = "Chaotic Skyflare Diamond makes crits do 209% damage of a normal hit. (150% x 3% =\n154.5%, with {spell:17959} / {spell:58435} the crit damage bonus is doubled, so 209%). It requires to have 2 Blue gems socketed to be activated. This can be achieved by using Purified Twilight Opal or other purple/green gems.\n\nCSD is the go-to Meta for all specializations due to {spell:17959}.\n\nChaotic Skyfire Diamond can also still be used, it serves the same purpose but you are leaving critical strike rating on the table." },
		{ slot = "Red", options = { { kind = "item", id = 42144, name = "Runed Dragon's Eye", skill = "Jewelcrafting" }, { kind = "item", id = 40113, name = "Runed Cardinal Ruby", tag = "P3" }, { kind = "item", id = 39998, name = "Runed Scarlet Ruby", tag = "P1-2" } },
		  note = "Pure spell power red gems are the go-to choice for warlocks in red sockets. If you have too little hit rating, you can use Veiled Monarch Topaz gems in your red slots instead. Phase 2 also introduces Runed Stormjewel of which you can equip one.\n\nIf you have Jewelcrafting you would replace three red gems with Runed Dragon's Eye in your gear." },
		{ slot = "Yellow", options = { { kind = "item", id = 40155, name = "Reckless Ametrine", tag = "P3" }, { kind = "item", id = 40051, name = "Reckless Monarch Topaz", tag = "P1-2" } },
		  note = "Spell power is our preferred stat, however sometimes it can be worthwhile to socket other gems than pure red gems because the socket bonus makes up for the difference in value. In such case orange gems with haste and spell power gives us the most bang for our buck.\n\nIf you are in dire need for hit rating you can also achieve some with your gems, although this is in general not recommended. This can either be done via pure yellow hit gems or orange ones in combination with spell power such as Veiled Monarch Topaz." },
		{ slot = "Blue", options = { { kind = "item", id = 40133, name = "Purified Dreadstone", tag = "P3" }, { kind = "item", id = 40026, name = "Purified Twilight Opal", tag = "P1-2" } },
		  note = "When you need to meet a meta gem requirement or have a very powerful socket bonus, you will want to use a blue gem. These spirit and spell power gems are the best choice when you do have to get some blue gems on your gear." },
	},
	priority = {
		{ 57946, "" },
		{ 17800, "" },
		{ 47813, "" },
		{ 65812, "" },
		{ 47864, "vs {spell:47865}" },
		{ 59164, "" },
		{ 47809, "vs {spell:47855}" },
	},
	opener = "The order we apply our initial spells influences how strong our {spell:47813} is. Before combat always start with {spell:57946} for Glyph of Life Tap. Make sure {spell:47893} is up as well as Grand Spellstone. A friendly reminder also to send in your upon the start of combat. Other things we can do before combat / early into the fight to maximize the {spell:47813} that we roll is the following:\n\n- Potion of Wild Magic (Increased crit chance) \n\n- Weapon Swap (swap back to normal weapons during the GCD from {spell:47813} application) \n\n- {spell:57934} before application (Damage %)\n\n- If someone else precast {spell:47809} for {spell:17800} you can opt to precast {spell:65812} instead\n\nNormal Op",
})

